/**
 * Data table Node - Version 1.1
 * Discriminator: resource=row, operation=insert
 */


// Helper types for special n8n fields
type ResourceMapperField = { id?: string; displayName?: string; required?: boolean; defaultMatch?: boolean; display?: boolean; type?: string; canBeUsedToMatch?: boolean; [key: string]: unknown };
type ResourceMapperCommon = { matchingColumns?: string[]; cachedResultName?: string; [key: string]: unknown };
type ResourceMapperValue = ResourceMapperCommon & { mappingMode: string; value?: null | Record<string, unknown>; schema?: ResourceMapperField[] };

/** Insert a new row */
export type DataTableV11RowInsertParams = {
  /**
   * <patterns>
   * <pattern title="Insert with explicit schema">
   * const storeData = node({
   *   type: 'n8n-nodes-base.dataTable',
   *   version: 1.1,
   *   config: {
   *     name: 'Store Data',
   *     parameters: {
   *       resource: 'row',
   *       operation: 'insert',
   *       dataTableId: { __rl: true, mode: 'name', value: 'my-table' },
   *       columns: {
   *         mappingMode: 'defineBelow',
   *         value: {
   *           name: expr('{{ $json.name }}'),
   *           email: expr('{{ $json.email }}')
   *         },
   *         schema: [
   *           { id: 'name', displayName: 'name', required: false, defaultMatch: false, display: true, type: 'string', canBeUsedToMatch: true },
   *           { id: 'email', displayName: 'email', required: false, defaultMatch: false, display: true, type: 'string', canBeUsedToMatch: true }
   *         ]
   *       }
   *     }
   *   }
   * });
   * </pattern>
   * </patterns>
   */
  resource: 'row';
  operation: 'insert';
/**
 * Data table
 * @builderHint Default to mode: 'list' which is easier for users to set up
 * @searchListMethod tableSearch
 * @default {"mode":"list","value":""}
 */
    dataTableId?: { __rl: true; mode: 'list' | 'name' | 'id'; value: string; cachedResultName?: string };
/**
 * Columns
 * @default {"mappingMode":"defineBelow","value":null}
 */
    columns?: ResourceMapperValue;
/**
 * Options
 * @default {}
 */
    options?: {
    /** Whether to improve bulk insert performance 5x by not returning inserted data
     * @default false
     */
    optimizeBulk?: boolean;
  };
};

export type DataTableV11RowInsertOutput = {
  createdAt?: string;
  id?: number;
  updatedAt?: string;
};

export type DataTableV11RowInsertNode = {
  type: 'n8n-nodes-base.dataTable';
  version: 1.1;
  config: NodeConfig<DataTableV11RowInsertParams>;
  output?: Items<DataTableV11RowInsertOutput>;
};